use semio_framework_os_kernel::{DslValue,sqlite_snapshot::artifact::NativeEncodingBound};
use crate::{PlaybookExpr,PlaybookFlowChild};
fn text(b:&mut NativeEncodingBound<'_,'_>,v:&str)->Result<(),String>{b.repeated(v.len(),32)}
fn value(b:&mut NativeEncodingBound<'_,'_>,root:&DslValue)->Result<(),String>{let mut pending=vec![root];while let Some(v)=pending.pop(){b.add(128)?;match v{DslValue::Null|DslValue::Bool(_)=>{},DslValue::Number(_)=>b.add(2048)?,DslValue::String(s)=>text(b,s)?,DslValue::Bytes(v)=>b.repeated(v.len(),16)?,DslValue::Array(v)=>{b.check_rows(v.len().checked_add(pending.len()).ok_or("Playbook value frontier overflow")?)?;for v in v{b.checkpoint()?;pending.push(v);}},DslValue::Object(v)=>{b.check_rows(v.len().checked_add(pending.len()).ok_or("Playbook member frontier overflow")?)?;for(k,v)in v{text(b,k)?;pending.push(v);}}}}Ok(())}
fn expression(b:&mut NativeEncodingBound<'_,'_>,root:&PlaybookExpr)->Result<(),String>{let mut pending=vec![root];while let Some(v)=pending.pop(){b.add(256)?;match v{PlaybookExpr::Const{value:v}=>value(b,v)?,PlaybookExpr::Var{name}=>text(b,name)?,PlaybookExpr::Eq{left,right}=>{b.check_rows(pending.len().checked_add(2).ok_or("Playbook expression frontier overflow")?)?;pending.extend([left.as_ref(),right.as_ref()]);},PlaybookExpr::And{items}|PlaybookExpr::Or{items}=>{b.check_rows(items.len().checked_add(pending.len()).ok_or("Playbook expression frontier overflow")?)?;for item in items{b.checkpoint()?;pending.push(item);}},PlaybookExpr::Truthy{expr}=>pending.push(expr)}}Ok(())}
/// 📏️ Bounds only the optional exact local native scene without cloning or persisting it.
pub fn local_scene(child:&PlaybookFlowChild,b:&mut NativeEncodingBound<'_,'_>)->Result<(),String>{let Some(scene)=child.local_owner::<crate::PlaybookWorkingScene>()else{return Ok(())};b.check_rows(scene.steps.len())?;b.checkpoint()?;for step in &scene.steps{b.add(1024)?;text(b,&step.id)?;text(b,&step.title)?;if let Some(s)=&step.description{text(b,s)?}b.check_rows(step.blocks.len())?;for block in &step.blocks{b.add(8192)?;for s in[&block.id,&block.label,&block.kind]{text(b,s)?}for s in[&block.description,&block.placeholder,&block.unit,&block.text,&block.schema,&block.src,&block.accept,&block.fixture_slug]{if let Some(s)=s{text(b,s)?}}if let Some(v)=&block.default{value(b,v)?}if let Some(v)=&block.params{value(b,v)?}if let Some(v)=&block.condition{expression(b,v)?}if let Some(options)=&block.options{b.check_rows(options.len())?;for option in options{b.add(256)?;text(b,&option.value)?;text(b,&option.label)?}}if let Some(fields)=&block.fields{b.check_rows(fields.len())?;for field in fields{b.add(2304)?;text(b,&field.key)?;if let Some(label)=&field.label{text(b,label)?}}}}}Ok(())}
